import{_ as o,o as a,c as l,ag as e}from"./chunks/framework.QfQ7DfGu.js";const c=JSON.parse('{"title":"LoongArch相关文档","description":"","frontmatter":{"title":"LoongArch相关文档","outline":"deep"},"headers":[],"relativePath":"docs-la/index.md","filePath":"docs-la/index.md"}'),n={name:"docs-la/index.md"};function t(s,r,i,g,p,h){return a(),l("div",null,[...r[0]||(r[0]=[e('<h1 id="loongarch官方参考手册" tabindex="-1">LoongArch官方参考手册 <a class="header-anchor" href="#loongarch官方参考手册" aria-label="Permalink to &quot;LoongArch官方参考手册&quot;">​</a></h1><h2 id="_1-龙芯架构参考手册-卷一-基础架构" tabindex="-1"><strong>1. 龙芯架构参考手册 - 卷一：基础架构</strong> <a class="header-anchor" href="#_1-龙芯架构参考手册-卷一-基础架构" aria-label="Permalink to &quot;**1. 龙芯架构参考手册 - 卷一：基础架构**&quot;">​</a></h2><p>该手册介绍了龙芯架构中基础架构部分的内容，包括了</p><ul><li><strong>基础整型指令集</strong></li><li><strong>基础浮点指令集</strong></li><li><strong>特权资源架构</strong></li><li><strong>控制与状态寄存器CSR</strong></li><li><strong>存储管理</strong></li><li><strong>例外与中断</strong></li><li><strong>指令编码</strong></li></ul><p>等上述内容，具体可查看<a href="https://github.com/loongson/LoongArch-Documentation/releases/latest/download/LoongArch-Vol1-v1.10-CN.pdf" target="_blank" rel="noreferrer">这里</a>。</p><p>注意：上面的指令手册包括LoongArch64架构，LoongArch32S （标准版，Standard）架构！</p><h2 id="_2-龙芯架构32位精简版参考手册" tabindex="-1"><strong>2. 龙芯架构32位精简版参考手册</strong> <a class="header-anchor" href="#_2-龙芯架构32位精简版参考手册" aria-label="Permalink to &quot;**2. 龙芯架构32位精简版参考手册**&quot;">​</a></h2><p>该手册介绍了龙芯架构中基础架构部分的内容，包括了</p><ul><li><strong>基础整型指令集</strong></li><li><strong>基础浮点指令集</strong></li><li><strong>特权资源架构</strong></li><li><strong>控制与状态寄存器CSR</strong></li><li><strong>存储管理</strong></li><li><strong>例外与中断</strong></li><li><strong>指令编码</strong></li><li><strong>大约71条整形指令，73条浮点指令，共计140多条</strong></li></ul><p>注意：这个指令手册包括的是LoongArch32R （精简版，Reduced）架构！</p><p>我们龙芯杯比赛使用的就是此架构。</p><p>具体可查看这里<a href="https://loongson.cn/uploads/images/2025032109211238668.%E9%BE%99%E6%9E%B6%E6%9E%8432%E4%BD%8D%E7%B2%BE%E7%AE%80%E7%89%88%E5%8F%82%E8%80%83%E6%89%8B%E5%86%8C_r1p04.pdf" target="_blank" rel="noreferrer">精简版手册</a></p><h2 id="_3-loongarch应用程序二进制接口" tabindex="-1"><strong>3. LoongArch应用程序二进制接口</strong> <a class="header-anchor" href="#_3-loongarch应用程序二进制接口" aria-label="Permalink to &quot;**3. LoongArch应用程序二进制接口**&quot;">​</a></h2><p>该手册介绍了龙架构与应用程序相关的一些规范性内容：</p><ul><li>程序调用规约</li><li>寄存器使用说明</li><li>ELF相关内容</li><li>与龙架构相关的DWARF</li><li>等其他内容</li></ul><p>目前最新的版本是v2.50，在<a href="https://github.com/loongson/la-abi-specs/releases/download/v2.50/la-abi-v2.50.pdf" target="_blank" rel="noreferrer">这里下载</a></p><p>整个项目的仓库在<a href="https://github.com/loongson/la-abi-specs" target="_blank" rel="noreferrer">这里</a>。</p><h2 id="_4-龙架构工具链约定" tabindex="-1"><strong>4. 龙架构工具链约定</strong> <a class="header-anchor" href="#_4-龙架构工具链约定" aria-label="Permalink to &quot;**4. 龙架构工具链约定**&quot;">​</a></h2><p>《Toolchain Conventions of the LoongArch™ Architecture》</p><p>该手册介绍了龙架构工具链相关的一些规范性内容：</p><ul><li>目标指令架构Target ISA</li><li>配置目标ABI</li><li>C/C++一些预处理器的宏定义等</li><li>编译器的一下选项说明</li></ul><p>目前PDF版本在<a href="https://github.com/loongson/la-toolchain-conventions/releases/download/releases%2Fv1.2/la-tc-v1.2.pdf" target="_blank" rel="noreferrer">这里下载</a></p><p>整个项目的仓库在<a href="https://github.com/loongson/la-toolchain-conventions" target="_blank" rel="noreferrer">这里</a>。</p><h2 id="_5-龙架构汇编语言编程指导" tabindex="-1"><strong>5. 龙架构汇编语言编程指导</strong> <a class="header-anchor" href="#_5-龙架构汇编语言编程指导" aria-label="Permalink to &quot;**5. 龙架构汇编语言编程指导**&quot;">​</a></h2><p>该手册介绍了龙架构汇编相关的一些内容：</p><ul><li>寄存器的使用</li><li>寻址模式</li><li>汇编语言的指示符</li><li>一些内敛汇编</li><li>龙架构的伪指令（宏指令）</li><li>等等内容</li></ul><p>目前PDF版本在<a href="https://github.com/loongson/la-asm-manual/releases/download/release-1.1/la-asm-manual-v1.1.pdf" target="_blank" rel="noreferrer">这里下载</a></p><p>整个项目的仓库在<a href="https://github.com/loongson/la-asm-manual" target="_blank" rel="noreferrer">这里</a>。</p><hr><h2 id="下面是一些处理器相关的手册" tabindex="-1">下面是一些处理器相关的手册： <a class="header-anchor" href="#下面是一些处理器相关的手册" aria-label="Permalink to &quot;下面是一些处理器相关的手册：&quot;">​</a></h2><ul><li><p><a href="https://loongson.cn/uploads/images/2026022508441776242.%E9%BE%99%E8%8A%AF3C6000%E5%AF%84%E5%AD%98%E5%99%A8%E5%8F%8A%E4%BD%BF%E7%94%A8%E6%89%8B%E5%86%8C_V1.0.pdf" target="_blank" rel="noreferrer"><strong>龙芯3C6000</strong></a></p></li><li><p><a href="https://loongson.cn/uploads/images/2024072510054986439.Loongson3A6000%20user%20book_V1.2.pdf" target="_blank" rel="noreferrer"><strong>龙芯3A6000</strong></a></p></li><li><p><a href="https://loongson.cn/uploads/images/2022051617120455270.%E9%BE%99%E8%8A%AF3A5000_3B5000%E5%A4%84%E7%90%86%E5%99%A8%E5%AF%84%E5%AD%98%E5%99%A8%E4%BD%BF%E7%94%A8%E6%89%8B%E5%86%8C.pdf" target="_blank" rel="noreferrer"><strong>龙芯3A5000</strong></a></p></li><li><p><a href="https://loongson.cn/uploads/images/2025081209095325652.%E9%BE%99%E8%8A%AF2K2000%E5%A4%84%E7%90%86%E5%99%A8%E7%94%A8%E6%88%B7%E6%89%8B%E5%86%8C_V1.03.pdf" target="_blank" rel="noreferrer"><strong>龙芯2K2000</strong></a></p></li><li><p><a href="https://loongson.cn/uploads/images/2022090113542571398.%E9%BE%99%E8%8A%AF2K1000LA%E5%A4%84%E7%90%86%E5%99%A8%E7%94%A8%E6%88%B7%E6%89%8B%E5%86%8C.pdf" target="_blank" rel="noreferrer"><strong>龙芯2K1000LA</strong></a></p></li><li><p><a href="https://loongson.cn/uploads/images/2023042109174127550.%E9%BE%99%E8%8A%AF2K0500%E5%A4%84%E7%90%86%E5%99%A8%E6%95%B0%E6%8D%AE%E6%89%8B%E5%86%8C_v1.0.pdf" target="_blank" rel="noreferrer"><strong>龙芯2K0500</strong></a></p></li><li><p><a href="https://loongson.cn/uploads/images/2025060909243029508.%E9%BE%99%E8%8A%AF2K0300%E5%A4%84%E7%90%86%E5%99%A8%E7%94%A8%E6%88%B7%E6%89%8B%E5%86%8C_V1.01.pdf" target="_blank" rel="noreferrer"><strong>龙芯2K0300</strong></a></p></li><li><p><strong>2K3000</strong>: 待补充</p></li></ul>',31)])])}const d=o(n,[["render",t]]);export{c as __pageData,d as default};
